package com.bank.health.endpoint;

import com.bank.health.dependency.DatabaseConnection;

// Liveness = process healthy? Readiness = can serve traffic (deps OK)?
public class HealthEndpoint {
    private final DatabaseConnection db;
    private volatile boolean processHealthy = true;

    public HealthEndpoint(DatabaseConnection db) { this.db = db; }

    public void markProcessUnhealthy() { this.processHealthy = false; }

    // Liveness: is the JVM itself healthy (not deadlocked/OOM)?
    public HealthStatus liveness() {
        return processHealthy
                ? new HealthStatus(true, "process alive")
                : new HealthStatus(false, "process stuck - restart me");
    }

    // Readiness: can we actually serve requests right now? Check dependencies.
    public HealthStatus readiness() {
        if (!processHealthy) return new HealthStatus(false, "process unhealthy");
        boolean dbOk = db.ping();
        return dbOk
                ? new HealthStatus(true, "db reachable, pool healthy")
                : new HealthStatus(false, "db pool broken - not ready");
    }
}
