package com.bank.health.probe;

import com.bank.health.endpoint.HealthEndpoint;
import com.bank.health.endpoint.HealthStatus;
import java.util.logging.Logger;

// Polls health endpoints and makes restart/routing decisions like kubelet.
public class KubernetesProbe {
    private static final Logger log = Logger.getLogger(KubernetesProbe.class.getName());
    private final HealthEndpoint endpoint;
    private final int livenessFailureThreshold;
    private int consecutiveLivenessFailures = 0;

    public KubernetesProbe(HealthEndpoint endpoint, int livenessFailureThreshold) {
        this.endpoint = endpoint;
        this.livenessFailureThreshold = livenessFailureThreshold;
    }

    // Returns true if the container should be RESTARTED.
    public boolean checkLiveness() {
        HealthStatus s = endpoint.liveness();
        if (s.isUp()) { consecutiveLivenessFailures = 0; return false; }
        consecutiveLivenessFailures++;
        log.warning(() -> "LIVENESS probe failed (" + consecutiveLivenessFailures
                + "/" + livenessFailureThreshold + "): " + s.getDetail());
        if (consecutiveLivenessFailures >= livenessFailureThreshold) {
            log.severe("LIVENESS threshold reached -> RESTART container");
            consecutiveLivenessFailures = 0;
            return true;
        }
        return false;
    }

    // Returns true if the pod should be IN the traffic rotation.
    public boolean checkReadiness() {
        HealthStatus s = endpoint.readiness();
        if (s.isUp()) {
            log.fine(() -> "READINESS ok: " + s.getDetail());
        } else {
            log.warning(() -> "READINESS failed -> REMOVE from rotation: " + s.getDetail());
        }
        return s.isUp();
    }
}
