package com.bank.health.gateway;

import com.bank.health.endpoint.HealthEndpoint;
import java.util.logging.Logger;

// Independent routing layer: the gateway decides to route or not, itself.
public class GatewayHealthCheck {
    private static final Logger log = Logger.getLogger(GatewayHealthCheck.class.getName());
    private final HealthEndpoint endpoint;
    private final String instanceId;

    public GatewayHealthCheck(String instanceId, HealthEndpoint endpoint) {
        this.instanceId = instanceId;
        this.endpoint = endpoint;
    }

    public boolean shouldRoute() {
        boolean ready = endpoint.readiness().isUp();
        if (!ready) log.severe(() -> "GATEWAY removes " + instanceId + " from backend pool");
        else log.info(() -> "GATEWAY keeps " + instanceId + " in backend pool");
        return ready;
    }
}
