package com.bank.health;

import com.bank.health.dependency.DatabaseConnection;
import com.bank.health.endpoint.HealthEndpoint;
import com.bank.health.gateway.GatewayHealthCheck;
import com.bank.health.probe.KubernetesProbe;
import java.util.logging.*;

public class HealthDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(HealthDemo.class.getName());

        DatabaseConnection db = new DatabaseConnection();
        HealthEndpoint endpoint = new HealthEndpoint(db);
        KubernetesProbe probe = new KubernetesProbe(endpoint, 3);
        GatewayHealthCheck gateway = new GatewayHealthCheck("payment-1", endpoint);

        // Healthy instance: liveness ok, readiness ok, gateway routes.
        log.info("Liveness=" + endpoint.liveness() + " Readiness=" + endpoint.readiness());
        probe.checkLiveness();
        boolean route = gateway.shouldRoute();
        log.info("Routing to payment-1? " + route);

        // DEPENDENCY BREAKS: process alive but DB pool broken.
        log.severe("Database connection pool has broken (process still alive)");
        db.breakPool();

        // Liveness still passes (process is fine) so NOT restarted...
        boolean restart = probe.checkLiveness();
        log.info("Restart container? " + restart + " (process is alive)");
        // ...but readiness FAILS, so gateway + readiness pull it out of rotation.
        boolean readyNow = probe.checkReadiness();
        boolean routeNow = gateway.shouldRoute();
        log.severe("ALERT: payment-1 alive-but-not-ready. readiness=" + readyNow
                + ", gateway routing=" + routeNow + " -> page on-call");

        // Dependency repaired: readiness recovers, gateway routes again.
        db.repairPool();
        log.info("DB repaired. readiness=" + probe.checkReadiness()
                + ", gateway routing=" + gateway.shouldRoute());
    }
}

